changeSet.sql:
ALTER TABLE hiv_adherence_preparation ADD COLUMN IF NOT EXISTS enrollment_session_uuid VARCHAR(255);
COMMENT ON COLUMN hiv_adherence_preparation.enrollment_session_uuid IS 'UUID linking this adherence preparation record to a specific enrollment cycle. Generated in frontend when form loads.';
CREATE INDEX IF NOT EXISTS idx_adherence_prep_enrollment_session_uuid ON hiv_adherence_preparation(enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;

ALTER TABLE hiv_initial_clinical_evaluation ADD COLUMN IF NOT EXISTS enrollment_session_uuid VARCHAR(255);
COMMENT ON COLUMN hiv_initial_clinical_evaluation.enrollment_session_uuid IS 'UUID linking this ICE record to a specific enrollment cycle. Shared with AdherencePreparation and EnrollmentCommencement.';
CREATE INDEX IF NOT EXISTS idx_ice_enrollment_session_uuid ON hiv_initial_clinical_evaluation(enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ice_person_session ON hiv_initial_clinical_evaluation(person_uuid, enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;

ALTER TABLE hiv_enrollment_commencement ADD COLUMN IF NOT EXISTS enrollment_session_uuid VARCHAR(255);
COMMENT ON COLUMN hiv_enrollment_commencement.enrollment_session_uuid IS 'UUID linking this enrollment record to a specific enrollment cycle. Shared with AdherencePreparation and ICE.';
CREATE INDEX IF NOT EXISTS idx_enrollment_comm_enrollment_session_uuid ON hiv_enrollment_commencement(enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_enrollment_comm_person_session ON hiv_enrollment_commencement(person_uuid, enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;

ALTER TABLE hiv_observation ADD COLUMN IF NOT EXISTS enrollment_session_uuid VARCHAR(255);
COMMENT ON COLUMN hiv_observation.enrollment_session_uuid IS 'UUID linking this observation (Transfer OUT/IN) to a specific enrollment cycle for returning clients.';
CREATE INDEX IF NOT EXISTS idx_observation_enrollment_session_uuid ON hiv_observation(enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_observation_person_type_session ON hiv_observation(person_uuid, type, enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;

ALTER TABLE hiv_patient_transfer_in ADD COLUMN IF NOT EXISTS enrollment_session_uuid VARCHAR(255);
COMMENT ON COLUMN hiv_patient_transfer_in.enrollment_session_uuid IS 'UUID linking this transfer-in record to a specific enrollment cycle. Created when new patient transfers in.';
CREATE INDEX IF NOT EXISTS idx_transfer_in_enrollment_session_uuid ON hiv_patient_transfer_in(enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_transfer_in_person_session ON hiv_patient_transfer_in(person_uuid, enrollment_session_uuid) WHERE enrollment_session_uuid IS NOT NULL;

-- Drop foreign key constraint if exists
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'fk_adherence_prep_art_clinical'
        AND conrelid = 'hiv_adherence_preparation'::regclass
    ) THEN
        ALTER TABLE hiv_adherence_preparation DROP CONSTRAINT fk_adherence_prep_art_clinical;
        RAISE NOTICE 'Dropped constraint: fk_adherence_prep_art_clinical';
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Constraint fk_adherence_prep_art_clinical does not exist or already dropped';
END $$;

-- Drop index if exists
DROP INDEX IF EXISTS idx_adherence_prep_art_clinical_uuid;

-- Drop the column
ALTER TABLE hiv_adherence_preparation DROP COLUMN IF EXISTS art_clinical_uuid;
